{-# LANGUAGE OverloadedLists #-}
module Game.Characters.Classic (characters) where
import Game.Characters.Import
import qualified Game.Model.Skill as Skill
import qualified Game.Characters.ClassicRules as Rules

characters :: [Character]
characters = [
 Character "Shiore Orochimaru" 0 "Originally a genin from the Hidden Grass Village attending the Chuunin Exams, Shiore was killed by Orochimaru shortly before the exams began. Orochimaru then took over Shiore's body and used it as a disguise in order to infiltrate the Chuunin Exams and scout out the potential of Uchiha Sasuke as a future vessel." [] [[Rules.configure "Shiore Orochimaru" 0 Skill.new { Skill.name="Five Elements Seal", Skill.desc="Shiore seals one enemy, dealing 10 affliction damage to them for 3 turns. During this time, that enemy will deal 10 less non-affliction damage and their harmful skills will cost 1 additional random chakra.", Skill.classes=[Bane,Melee], Skill.cost=[Blood], Skill.cooldown=3 }],
    [Rules.configure "Shiore Orochimaru" 1 Skill.new { Skill.name="Giant Snake Bind", Skill.desc="Shiore summons a giant snake and binds one enemy, dealing 20 damage to them for 2 turns. The first turn, that enemy will be stunned for 1 turn.", Skill.classes=[Physical,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shiore Orochimaru" 2 Skill.new { Skill.name="Curse Seal", Skill.desc="Shiore places a curse seal on an enemy, stealing 5 health from them for 3 turns. While active, that enemy will be unable to become invulnerable*. During this time, if that enemy is killed, Shiore gains 1 random chakra*.", Skill.classes=[Bane,Melee], Skill.cost=[Rand], Skill.cooldown=3 }],
    [Rules.configure "Shiore Orochimaru" 3 Skill.new { Skill.name="Snake Body Replacement", Skill.desc="This skill makes Shiore Orochimaru invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shiore-orochimaru",
 Character "Cursed Seal Mizuki" 0 "Touji Mizuki is now a missing nin that has been corrupted by his own dark ambitions and the will of Orochimaru." [] [[Rules.configure "Cursed Seal Mizuki" 0 Skill.new { Skill.name="Curse Seal: Tiger", Skill.desc="By drinking a curse seal potion, Mizuki transforms into a wild tiger. The following 3 turns, Mizuki will gain 35 points of destructible defense and during this time, 'Curse Seal: Tiger Punch' will be >improved and 'Puppets Genjutsu' will be replaced by its alternate version.", Skill.classes=[Chakra], Skill.cost=[Blood], Skill.cooldown=3 }],
    [Rules.configure "Cursed Seal Mizuki" 1 Skill.new { Skill.name="Curse Seal: Tiger Punch", Skill.desc="Mizuki fiercely punches one enemy, dealing 30 damage to them. For 2 turns, that enemy's skills will deal 15 less non-affliction damage. During 'Curse Seal: Tiger', this skill is improved and will deal 45 damage instead. This skill does not stack.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Rand], Skill.cooldown=0 }],
    [Rules.configure "Cursed Seal Mizuki" 2 Skill.new { Skill.name="Puppets Genjutsu", Skill.desc="Mizuki puts an enemy under a genjutsu. For 2 turns, that enemy will be unable to reduce damage or become invulnerable, and their skills will deal 5 less damage and will cost 1 additional random chakra. During this time, if that enemy does not use a new skill, they will take 10 damage.", Skill.classes=[Mental,Ranged], Skill.cost=[Gen], Skill.cooldown=2 },Rules.configure "Cursed Seal Mizuki" 4 Skill.new { Skill.name="Curse Seal: Tiger Bomb", Skill.desc="Mizuki charges like a bomb, dealing 45 damage to one enemy and becoming invulnerable for 1 turn.", Skill.classes=[Physical,Melee], Skill.cost=[Blood,Rand], Skill.cooldown=1 }],
    [Rules.configure "Cursed Seal Mizuki" 3 Skill.new { Skill.name="Evil Intentions", Skill.desc="This skill makes Cursed Seal Mizuki invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-cursed-seal-mizuki",
 Character "Shizune (S)" 0 "Having spent the past few years as the right-hand woman and de facto secretary to the Fifth Hokage, Shizune has matured and become more experienced. Still a top-class medical-nin, Shizune has also become proficient at sealing jutsu, defensive chakra control, and strategically utilizing her summon Katsuyu." [] [[Rules.configure "Shizune (S)" 0 Skill.new { Skill.name="Full Team Recovery", Skill.desc="Shizune instantly heals herself and her allies for 15 health. During 'Chakra Reinforcement', this skill will heal Shizune and her allies for 20 health.", Skill.classes=[Chakra], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Shizune (S)" 1 Skill.new { Skill.name="Katsuyu Interception", Skill.desc="Shizune calls upon Katsuyu to protect herself or an ally. For 1 turn, the first harmful skill used on the protected ally will be countered. This skill is invisible.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=2 }],
    [Rules.configure "Shizune (S)" 2 Skill.new { Skill.name="Chakra Reinforcement", Skill.desc="For 3 turns, Shizune will have 10 points of damage reduction. During this time, 'Full Team Recovery' will be improved. The following 3 turns, this skill will be replaced by 'Four-Corner Sealing Barrier'.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=3 },Rules.configure "Shizune (S)" 4 Skill.new { Skill.name="Four-Corner Sealing Barrier", Skill.desc="Shizune seals one enemy inside a four-corner barrier, dealing 25 damage to them. Afterwards, Shizune will become invulnerable for 1 turn.", Skill.classes=[Mental,Ranged], Skill.cost=[Gen], Skill.cooldown=0 }],
    [Rules.configure "Shizune (S)" 3 Skill.new { Skill.name="Sliding Dodge", Skill.desc="This skill makes Shizune (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shizune-s",
 Character "Fuuton Naruto (S)" 0 "During his training under Kakashi and Yamato, Naruto discovers his affinity for Wind Release. By using shadow clones to accelerate his progress, he learns to combine wind-nature chakra with the Rasengan and creates the devastating Rasenshuuriken." [] [[Rules.configure "Fuuton Naruto (S)" 0 Skill.new { Skill.name="Fuuton: Rasengan", Skill.desc="Using the wind-style version of the Rasengan, Naruto deals 25 piercing damage to one enemy. During 'Mass Shadow Clones', this skill will apply once 'Wind Destruction' on all enemies.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Fuuton Naruto (S)" 1 Skill.new { Skill.name="Fuuton: Rasenshuuriken", Skill.desc="Using his recently created clones, Naruto hurls an even more powerful Rasengan at one enemy, dealing 40 piercing damage to them. During 'Mass Shadow Clones', this skill will apply twice 'Wind Destruction' on all enemies.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin,Gen], Skill.cooldown=1 }],
    [Rules.configure "Fuuton Naruto (S)" 2 Skill.new { Skill.name="Mass Shadow Clones", Skill.desc="Naruto gains 5 clones, granting himself 10% unpierceable damage reduction for each clone. If a new non-affliction damage skill is used on Naruto, he will lose 1 clone. During this time, Naruto improves his skills and loses 2 clones whenever he uses one of them. This skill cannot be used while active.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Fuuton Naruto (S)" 3 Skill.new { Skill.name="Kyuubi Insight", Skill.desc="This skill makes Fuuton Naruto invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-fuuton-naruto-s",
 Character "Hebi Sasuke (S)" 0 "After breaking ties with Orochimaru, Sasuke forms Hebi and begins his hunt for Itachi. With greater control over the Cursed Seal and his lightning-nature chakra, Sasuke combines sudden Chidori attacks, automatic defenses, and the overwhelming power of Kirin." [] [[Rules.configure "Hebi Sasuke (S)" 0 Skill.new { Skill.name="Chidori Surprise Attack", Skill.desc="Sasuke catches one enemy off guard with Chidori, dealing 20 piercing damage to them. The following 3 turns, Sasuke's skills will deal 10 additional damage.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "Hebi Sasuke (S)" 1 Skill.new { Skill.name="Cursed Seal: Automatic Protection", Skill.desc="For 1 turn, the first harmful skill used on Sasuke will be countered. If successful, the countered enemy will take 10 piercing damage and Sasuke will gain 10 points of destructible defense. This skill is invisible.", Skill.classes=[Chakra], Skill.cost=[Blood], Skill.cooldown=2 }],
    [Rules.configure "Hebi Sasuke (S)" 2 Skill.new { Skill.name="Kirin", Skill.desc="Harnessing natural lightning from the storm clouds above, Sasuke guides a massive thunderbolt onto one enemy, dealing 35 piercing damage to them. If that enemy's health drops to 15 or lower, they will be instantly killed. This skill cannot be countered.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand,Rand,Rand], Skill.cooldown=2 }],
    [Rules.configure "Hebi Sasuke (S)" 3 Skill.new { Skill.name="Sasuke Kunai Parry", Skill.desc="This skill makes Hebi Sasuke (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-hebi-sasuke-s",
 Character "Susanoo Sasuke (S)" 0 "Sasuke takes control of the powerful Susano'o, achieving a high level of strength with an unimaginable impenetrable defense. He can also still use other techniques of his Mangekyo Sharingan." [] [[Rules.configure "Susanoo Sasuke (S)" 0 Skill.new { Skill.name="Sasuke Susano'o", Skill.desc="Using his Susanoo, Sasuke gains 50 points of destructible defense permanent and may use his skills. During this time, this skill is replaced and Sasuke will ignore any effects that destroy destructible defense. When this defense is destroyed, Sasuke will be stunned for 2 turns.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=0 },Rules.configure "Susanoo Sasuke (S)" 4 Skill.new { Skill.name="Sasuke Mangekyo Sharingan", Skill.desc="Sasuke activates his Mangekyou Sharingan and gains 25% unpierceable damage reduction until 'Sasuke Susano'o' destructible defense is destroyed. When this skill is used, the cooldown of 'Spreading Amaterasu' is reset.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Susanoo Sasuke (S)" 1 Skill.new { Skill.name="Susano'o Arrow", Skill.desc="Using his Susano'o bow, Sasuke destroys all destructible defense of one enemy and deals 20 piercing damage and an additional 5 damage for each 10 points of destructible defense that 'Sasuke Susano'o' currently has. This skill requires 'Sasuke Susano'o'.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood], Skill.cooldown=0 }],
    [Rules.configure "Susanoo Sasuke (S)" 2 Skill.new { Skill.name="Spreading Amaterasu", Skill.desc="Susanoo Sasuke deals 2 affliction damage to one enemy permanently. This skill will double its damage everytime that enemy uses a new skill. This skill cannot be removed and it requires 'Sasuke Susano'o'. This skill will have its cooldown reset if the enemy target is killed.", Skill.classes=[Bane,Ranged], Skill.cost=[Rand], Skill.cooldown=5 }],
    [Rules.configure "Susanoo Sasuke (S)" 3 Skill.new { Skill.name="Mangekyo Insight", Skill.desc="This skill makes Susanoo Sasuke (S) invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-susanoo-sasuke-s",
 Character "Raikage (S)" 0 "Ay is the fourth Raikage of Hidden Cloud Ninja and supreme leader of the Shinobi Alliance. Son of the Third Raikage, he is also Killer Bee's older brother." [] [[Rules.configure "Raikage (S)" 0 Skill.new { Skill.name="Lightning Release", Skill.desc="Using lightning, Raikage will permanently deal 10 additional damage until he uses a new harmful skill. While active, he gains 10 points of damage reduction. Each time this skill is used, it costs 1 additional random chakra, its bonus damage increases by 10, and grants 5 additional points of damage reduction.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Raikage (S)" 1 Skill.new { Skill.name="Liger Bomb", Skill.desc="Raikage lifts one enemy in the air and then brutaly smashes their head fist into ground, dealing 30 damage to them and lowering their non-affliction damage by 15 for 1 turn. The following turn, that enemy's skills will be stunned.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Rand], Skill.cooldown=1 }],
    [Rules.configure "Raikage (S)" 2 Skill.new { Skill.name="Lightning Oppression Horizontal", Skill.desc="Raikage performs a backhanded horizontal chop againts one enemy, destroying all destructible defense and dealing 20 piercing damage.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Raikage (S)" 3 Skill.new { Skill.name="Lightning Speed", Skill.desc="This skill makes Raikage (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-raikage-s",
 Character "Mifune (S)" 0 "Mifune is a samurai and leader of the Land of Iron, and now in the war he is the commander of the fourth division. His unmatched swordsmanship makes him capable of attacking and counterattacking any enemy regardless of how fast their movements are." [] [[Rules.configure "Mifune (S)" 0 Skill.new { Skill.name="Samurai Troops", Skill.desc="By commanding his samurai troops, Mifune deals 5 piercing damage to all enemies and makes them deal 5 less non-affliction damage for 1 turn. Also for 1 turn, all Mifune team will deal 5 more damage from melee skills. This skill becomes 'Flash' with a bloodline cost.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand], Skill.cooldown=2 },Rules.configure "Mifune (S)" 4 Skill.new { Skill.name="Flash", Skill.desc="With his more powerful cut, Mifune deals 30 piercing damage to one enemy and stuns their non-mental skills. This skill costs a specific chakra depending on the skill that is replaced by it.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood], Skill.cooldown=1 }],
    [Rules.configure "Mifune (S)" 1 Skill.new { Skill.name="Iaito", Skill.desc="Reacting one enemy move, Mifune deals them 15 piercing damage and becomes invulnerable from physical skills for 1 turn. This skill becomes 'Flash' with a taijutsu cost.", Skill.classes=[Physical,Melee], Skill.cost=[Rand], Skill.cooldown=2 },Rules.configure "Mifune (S)" 4 Skill.new { Skill.name="Flash", Skill.desc="With his more powerful cut, Mifune deals 30 piercing damage to one enemy and stuns their non-mental skills. This skill costs a specific chakra depending on the skill that is replaced by it.", Skill.classes=[Chakra,Ranged], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Mifune (S)" 2 Skill.new { Skill.name="Raiton Pierce", Skill.desc="Mifuse uses a fast lightning chakra stab to one enemy, dealing them 15 piercing damage and makes them invulnerable from new helpful skills. This skill becomes 'Flash' with a genjutsu cost.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=2 },Rules.configure "Mifune (S)" 4 Skill.new { Skill.name="Flash", Skill.desc="With his more powerful cut, Mifune deals 30 piercing damage to one enemy and stuns their non-mental skills. This skill costs a specific chakra depending on the skill that is replaced by it.", Skill.classes=[Chakra,Ranged], Skill.cost=[Gen], Skill.cooldown=1 }],
    [Rules.configure "Mifune (S)" 3 Skill.new { Skill.name="Samurai Guard", Skill.desc="This skill makes Mifune (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-mifune-s",
 Character "Karatachi Yagura" 0 "The Fourth Mizukage of the Hidden Mist Village, Yagura is also the jinchuuriki host of the Three-Tailed Beast, Isobu. A tragic character manipulated by \"Uchiha Madara\" throughout his infamously bloody reign, Yagura uses the Three-Tails' unique mist and coral-based abilities in battle to efficiently hinder his enemies." [] [[Rules.configure "Karatachi Yagura" 0 Skill.new { Skill.name="Isobu: Tailed Beast Bomb", Skill.desc="Yagura heals 5 health and deals 20 damage to one enemy. This skill  deals 10 additional damage  for every 15 extra health it heals.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "Karatachi Yagura" 1 Skill.new { Skill.name="Bloodshed", Skill.desc="Yagura deals 10 piercing damage to all enemies. For 2 turns, if an enemy does not use a new skill, their skills will have 1 additional cooldown for 1 turn, otherwise, 'Isobu: Tailed Beast Bomb' will heal 5 additional health permanently. This skill stacks and cannot be countered.", Skill.classes=[Mental], Skill.cost=[Blood], Skill.cooldown=1 }],
    [Rules.configure "Karatachi Yagura" 2 Skill.new { Skill.name="Isobu Transformation", Skill.desc="For 1 turn, Yagura will ignore stun effects and 'Bloodshed' will cost 1 random chakra. Permanently, everytime Yagura uses a new skill, he will ignore all stun effects for 1 turn. During this time, this skill can be used to make 'Bloodshed'  cost 1 random chakra for 1 turn. This skill cannot be removed.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=2 }],
    [Rules.configure "Karatachi Yagura" 3 Skill.new { Skill.name="Isobu: Chakra Skin", Skill.desc="This skill makes Yagura invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-karatachi-yagura",
 Character "Guren (S)" 0 "One of Orochimaru's highest-ranking subordinates, Guren is a sadistic, proud, and ambitious woman, and is utterly devoted to Orochimaru, considered one of his most promising potential vessels. Possessing the Crystal Release kekkei genkai, Guren is able to create crystals for a wide range of combat purposes." [] [[Rules.configure "Guren (S)" 0 Skill.new { Skill.name="Crystal Dragon", Skill.desc="Guren sends a massive crystal dragon towards one enemy, dealing 35 damage to them and stunning their skills for 1 turn. The following turn, that enemy will receive 10 additional damage from 'Crystal Barrage'. This skill will be replaced by 'Crystal Barrage' permanently.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=1 },Rules.configure "Guren (S)" 4 Skill.new { Skill.name="Crystal Barrage", Skill.desc="Guren unleashes a barrage of crystal spikes, dealing 25 damage to all enemis. After this skill is used, it will be replaced by 'Crystal Dragon'.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 }],
    [Rules.configure "Guren (S)" 1 Skill.new { Skill.name="Crystal Prison", Skill.desc="Guren encases an enemy in a crystal prison. For 1 turn, that enemy will become invulnerable to helpful skills. The following turn, this skill will be replaced 'Crystal Break'.", Skill.classes=[Chakra,Melee], Skill.cost=[Rand], Skill.cooldown=0 },Rules.configure "Guren (S)" 5 Skill.new { Skill.name="Crystal Break", Skill.desc="Guren crushes the enemy affected by 'Crystal Prison', dealing 30 piercing damage to them.", Skill.classes=[Chakra,Melee], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Guren (S)" 2 Skill.new { Skill.name="Crystal Clone", Skill.desc="Guren forms a crystal clone. For 1 turn, the first harmful skill used against her will be countered, and the countered enemy will take 20 piercing damage*. This skill is invisible and ends when triggered.", Skill.classes=[Chakra,Melee], Skill.cost=[Blood], Skill.cooldown=2 }],
    [Rules.configure "Guren (S)" 3 Skill.new { Skill.name="Crystal Formation: Arrow of Light", Skill.desc="This skill makes Guren (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-guren-s",
 Character "True Art Deidara (S)" 0 "A fanatical explosive artist who believes true art exists only in a single, beautiful moment of destruction. Deidara specializes in long-term setup and devastating payoffs, planting microscopic bombs that turn the battlefield into a ticking masterpiece." [] [[Rules.configure "True Art Deidara (S)" 0 Skill.new { Skill.name="Clay Dolls", Skill.desc="Deidara gains 15 points of destructible defense. While he has this defense up, each turn he will target a random enemy, dealing 10 damage to them and making them receive 5 additional non-affliction damage from Deidara's other skills.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "True Art Deidara (S)" 1 Skill.new { Skill.name="C2: Dragon", Skill.desc="For 3 turns, Deidara gains 20 points of destructible defense and targets all enemies. Any enemy that uses a new harmful skill will take 10 piercing damage. While active, this skill will be replaced by 'Dragon Missile'.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand,Rand], Skill.cooldown=4 },Rules.configure "True Art Deidara (S)" 4 Skill.new { Skill.name="Dragon Missile", Skill.desc="Deidara deals 25 damage to one enemy. This skill ignores invulnerability.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "True Art Deidara (S)" 2 Skill.new { Skill.name="C4: Karura", Skill.desc="Deidara releases a cloud of microscopic bomb towards on enemy, dealing 3 affliction damage to them permanently. This skill will double its damage each turn.", Skill.classes=[Bane,Ranged], Skill.cost=[Blood,Nin], Skill.cooldown=6 }],
    [Rules.configure "True Art Deidara (S)" 3 Skill.new { Skill.name="C4: Trap", Skill.desc="This skill makes True Art Deidara (S) invulnerable for 1 turn. After Deidara uses 5 new skills, 'C4: Trap' will be replaced by 'C0: Final Explosion'.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 },Rules.configure "True Art Deidara (S)" 5 Skill.new { Skill.name="C0: Final Explosion", Skill.desc="Deidara sacrifices himself, dealing 40 piercing damage to all enemies. Afterwards, Deidara is instantly killed. This skill may only be used when Deidara uses 5 new skills.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin,Blood,Rand], Skill.cooldown=2 }] ] Original "classic-true-art-deidara-s",
 Character "Kisame Body Double (S)" 0 "By using one of Pein's techniques a Sand Nin spy for Akatsuki is changed to look like Kisame. The body double is controlled by Kisame but only has a third of his chakra." [] [[Rules.configure "Kisame Body Double (S)" 0 Skill.new { Skill.name="Five Man-Eating Sharks", Skill.desc="Kisame summons five sharks of water, dealing 25 damage to one enemy for 2 turns. During this time, that enemy will deal 10 less non-affliction damage. During 'Explosive Water Shock Wave', this skill will cost 1 less random chakra.", Skill.classes=[Physical,Ranged], Skill.cost=[Nin,Rand], Skill.cooldown=0 }],
    [Rules.configure "Kisame Body Double (S)" 1 Skill.new { Skill.name="Water Prison Technique", Skill.desc="Using a bubble of water, Kisame deals 15 affliction damage to one enemy and stuns their non-mental skills for 1 turn. During this time, that enemy will become invulnerable to helpful skills. During 'Explosive Water Shock Wave', this skill will cost 1 random chakra.", Skill.classes=[Bane,Melee], Skill.cost=[Blood], Skill.cooldown=1 }],
    [Rules.configure "Kisame Body Double (S)" 2 Skill.new { Skill.name="Explosive Water Shock Wave", Skill.desc="Kisame fills the battlefield with water. For 4 turns, Kisame and his allies will lose 1 less chakra from chakra removal or stealing effects used on them and all enemies that use a new skill will have the cooldown of that skill increased by 1 turn.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=4 }],
    [Rules.configure "Kisame Body Double (S)" 3 Skill.new { Skill.name="Kisame Water Clone", Skill.desc="This skill makes Kisame Body Double (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-kisame-body-double-s",
 Character "Itachi Body Double (S)" 0 "By using one of Pein's techniques a Sand Nin spy for Akatsuki is changed to look like Itachi. The body double is controlled by Itachi but only has a third of his chakra." [] [[Rules.configure "Itachi Body Double (S)" 0 Skill.new { Skill.name="Finger Genjutsu", Skill.desc="Itachi affects one enemy with Finger Genjutsu for 1 turn. If the affected enemy uses any skill on Itachi Body Double (S) or his allies that skill will be countered and that enemy will take 10 damage and Itachi Body Double (S) will gain 1 genjutsu chakra. The target of this skill is invisible.", Skill.classes=[Mental,Ranged], Skill.cost=[Gen], Skill.cooldown=1 }],
    [Rules.configure "Itachi Body Double (S)" 1 Skill.new { Skill.name="Genjutsu Reversal", Skill.desc="For 2 turns, the first harmful skill used on Itachi Body Double (S) each turn will be reflected back onto the enemy who used it. This skill is invisible.", Skill.classes=[Mental], Skill.cost=[Blood,Gen], Skill.cooldown=4 }],
    [Rules.configure "Itachi Body Double (S)" 2 Skill.new { Skill.name="Goukakyuu no Jutsu", Skill.desc="Itachi Body Double (S) creates a large fireball that scorches the battlefield, dealing 20 affliction damage to one enemy. The following turn, all enemies will take 10 affliction damage.*", Skill.classes=[Bane,Ranged], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Itachi Body Double (S)" 3 Skill.new { Skill.name="Illusionary Raven Bunshin", Skill.desc="This skill makes Itachi Body Double (S) invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-itachi-body-double-s",
 Character "Sasori of the Red Sand (S)" 0 "Sasori is a senior Akatsuki member and a legendary puppet master. He is even rumored to have defeated an entire nation with puppets alone. ORIGINAL DESIGN: Pavera" [] [[Rules.configure "Sasori of the Red Sand (S)" 0 Skill.new { Skill.name="Thousand Hands", Skill.desc="Using this skill, Sasori deals 10 damage to an enemy for 2 turns and gains 5 points of destructible defense each turn. If 'Poison Gas' is used on the target in the following turn, it will last 1 additional turn on them.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand], Skill.cooldown=1 },Rules.configure "Sasori of the Red Sand (S)" 5 Skill.new { Skill.name="Satetsu Kesshu", Skill.desc="Sasori creates a giant sphere of branching spikes. This skill deals 25 piercing damage to all enemies. If an enemy's health drops to 10 or lower, they will be killed. This skill cannot be countered or reflected.", Skill.classes=[Physical,Ranged], Skill.cost=[Blood,Nin,Rand], Skill.cooldown=3 }],
    [Rules.configure "Sasori of the Red Sand (S)" 1 Skill.new { Skill.name="Poison Gas", Skill.desc="Sasori deals 5 affliction damage to all enemies for 5 turns. During this time, Sasori gains 5 points of destructible defense and any enemy that uses a new harmful skill will be dealt 5 affliction damage. This skill lasts 1 additional turn on an enemy affected by 'Thousand Hands'. This skill cannot be countered and ends when Sasori is killed.", Skill.classes=[Bane,Ranged], Skill.cost=[Rand,Rand], Skill.cooldown=4 }],
    [Rules.configure "Sasori of the Red Sand (S)" 2 Skill.new { Skill.name="Iron Sand", Skill.desc="Sasori summons the Third Kazekage's puppet for 3 turns. Each turn, Sasori gains 10 permanent destructible defense and any enemy that uses a new harmful skill on Sasori will take 5 piercing damage. During this time, this skill becomes 'Satetsu Kaiho' and 'Thousand Hands' becomes 'Satetsu Kesshu'.", Skill.classes=[Physical], Skill.cost=[Blood], Skill.cooldown=4 },Rules.configure "Sasori of the Red Sand (S)" 4 Skill.new { Skill.name="Satetsu Kaiho", Skill.desc="Sasori gathers a great volume of iron sand. This skill deals 30 piercing damage to one enemy. For 2 turns, that enemy will be unable to reduce damage or become invulnerable. Afterwards, Sasori gains 15 points of destructible defense for 1 turn.", Skill.classes=[Physical,Ranged], Skill.cost=[Nin,Rand], Skill.cooldown=0 }],
    [Rules.configure "Sasori of the Red Sand (S)" 3 Skill.new { Skill.name="Puppet Protection", Skill.desc="This skill makes Sasori invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-sasori-of-the-red-sand-s",
 Character "Samehada Fusion Kisame (S)" 0 "After merging with the sentient blade Samehada, Kisame transforms into a monstrous shark-like being. In this form, he reigns supreme underwater, draining chakra upon contact and relentlessly hunting his prey within a vast, moving prison of water." [] [[Rules.configure "Samehada Fusion Kisame (S)" 0 Skill.new { Skill.name="Water Prison Shark Dance", Skill.desc="For 3 turns, all enemies and all allies will have the cost of their harmful skills increased by 1 random chakra, while Kisame's harmful skills will cost 1 less random chakra. During this time, any target that uses a new harmful skill will ignore 'Water Prison Shark Dance' for 1 turn. This skill ends when Kisame dies.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=3 }],
    [Rules.configure "Samehada Fusion Kisame (S)" 1 Skill.new { Skill.name="Non-Stop Hunting", Skill.desc="Kisame relentlessly hunts an enemy from underwater. For 2 turns, Kisame will deal 20 piercing damage to that enemy and remove 1 random chakra from them each turn.", Skill.classes=[Physical,Melee], Skill.cost=[Blood,Rand,Rand], Skill.cooldown=1 }],
    [Rules.configure "Samehada Fusion Kisame (S)" 2 Skill.new { Skill.name="Great Water Shark Missile", Skill.desc="Kisame launches a massive shark-shaped water missile, dealing 25 damage to all enemies and removing 1 random chakra from a random enemy. Afterwards, Kisame gains 15 points of destructible defense. This skill cannot be countered.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Nin,Rand], Skill.cooldown=2 }],
    [Rules.configure "Samehada Fusion Kisame (S)" 3 Skill.new { Skill.name="Shark Skin", Skill.desc="This skill makes Samehada Fusion Kisame (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-samehada-fusion-kisame-s",
 Character "Susanoo Itachi (S)" 0 "After using Amaterasu and Tsukuyomi, Itachi awakened his triumph, Susanoo, and became even stronger, both defensively with his Yata Mirror and offensively with his Totsuka Sword capable of sealing an opponent." [] [[Rules.configure "Susanoo Itachi (S)" 0 Skill.new { Skill.name="Susanoo Activation", Skill.desc="Uchiha Itachi activates Susanoo, and he takes 20 affliction damage*. Each turn he gains 5 permanent stacking destructible defense and his skills become usable for the rest of the game. This skill cannot be used while it's active.", Skill.classes=[Bane], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Susanoo Itachi (S)" 1 Skill.new { Skill.name="Totsuka Sword", Skill.desc="Itachi uses the legendary blade of Susanoo, dealing 25 piercing damage to one enemy and removing 1 genjutsu or bloodline chakra from them. This skill requires 'Susanoo Activation'.'", Skill.classes=[Chakra,Melee], Skill.cost=[Gen], Skill.cooldown=0 }],
    [Rules.configure "Susanoo Itachi (S)" 2 Skill.new { Skill.name="Yata Mirror", Skill.desc="Using the legendary shield of Susanoo, Itachi (S) ignores all harmful effects used on him for 1 turn. Any enemy that uses a new skill on him will have the cost of their skills increased by 1 random chakra for 1 turn. This skill is invisible and requires 'Susanoo Activation'.", Skill.classes=[Chakra], Skill.cost=[Gen], Skill.cooldown=2 }],
    [Rules.configure "Susanoo Itachi (S)" 3 Skill.new { Skill.name="Susanoo Defense", Skill.desc="This skill makes Susanoo Itachi (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-susanoo-itachi-s",
 Character "Yahiko (S)" 0 "The leader of the original Akatsuki and one of the three Rain Orphans mentored by Jiraiya, Yahiko was a dear friend of Nagato and Konan and a highly idealistic person. Striving for world peace, Yahiko established the Akatsuki, leading them through the war-torn reality of their time with a 'kill or be killed' philosophy." [] [[Rules.configure "Yahiko (S)" 0 Skill.new { Skill.name="Wild Rip Wave", Skill.desc="Yahiko throws a wave, dealing 25 damage to all enemies. For 1 turn, Yahiko's team will heal 5 health and ignore affliction damage.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin,Rand], Skill.cooldown=1 }],
    [Rules.configure "Yahiko (S)" 1 Skill.new { Skill.name="Water Pillar", Skill.desc="Yahiko targets one ally permanently. The first harmful skill used on that ally will be reflected to Yahiko. If successful, that ally will heal 20 health and gain 15 points of destructible defense. This skill is invisible and cannot be used on an already affected ally. This skill ends when Yahiko is killed.", Skill.classes=[Chakra], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Yahiko (S)" 2 Skill.new { Skill.name="Final Command", Skill.desc="This skill can only be used when Yahiko has 25 health or less. Yahiko chooses one ally to execute him, killing himself instantly. Afterwards, that ally enters a bloodthirsty rage. For 2 turns, they will deal 15 additional damage, ignore stun effects, and gain 1 random chakra each turn.", Skill.classes=[Physical], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Yahiko (S)" 3 Skill.new { Skill.name="Squad Leader", Skill.desc="For 1 turn, all new harmful skills used on Yahiko's allies will be reflected back to him. During this time, Yahiko gains 15 points of unpierceable damage reduction and becomes immune to affliction damage.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand], Skill.cooldown=3 }] ] Original "classic-yahiko-s",
 Character "Female Animal Path Pein (S)" 0 "One of Nagato's Six Paths of Pain, the Female Animal Path is a relentless and tactical combatant who overwhelms her enemies through the summoning of massive, destructive creatures. Calm and emotionless, she specializes in battlefield control, using her summons to pressure multiple opponents at once while remaining difficult to pin down." [] [[Rules.configure "Female Animal Path Pein (S)" 0 Skill.new { Skill.name="Animal Path Summoning", Skill.desc="Female Animal Path summons all pre-selected animals to the battlefield. For each animal summoned, Female Animal Path gains 5 destructible defense. Animals, when summoned, cannot be pre-selected for the following 3 turns. This skill will cost 1 additional random chakra for each pre-selected animal. This skill ignores invulnerability and cannot be countered or reflected.", Skill.classes=[Chakra], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "Female Animal Path Pein (S)" 1 Skill.new { Skill.name="Rampaging Buffalo", Skill.desc="Pre-selects this animal for the next use of 'Animal Path Summoning'. When active, deals 10 damage to all enemies for 3 turns. During this time, any enemy that does not use a new skill will take another 10 damage. This skill will be replaced by 'Stampeding Rhino'.", Skill.classes=[Physical,Melee], Skill.cost=[], Skill.cooldown=0 },Rules.configure "Female Animal Path Pein (S)" 4 Skill.new { Skill.name="Stampeding Rhino", Skill.desc="Pre-selects this animal for the next use of 'Animal Path Summoning'. For 3 turns, each turn a random enemy will take 20 damage and will have their non-mental skills stunned for 1 turn. This skill will be replaced by 'Rampaging Buffalo' after use.", Skill.classes=[Physical,Melee], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Female Animal Path Pein (S)" 2 Skill.new { Skill.name="Venomous Centipede", Skill.desc="Pre-selects this animal for the next use of 'Animal Path Summoning'. When active, Female Animal Path grants her team 15 points of destructible defense and any enemy that destroys it will take 5 affliction damage* for 3 turns.", Skill.classes=[Physical,Bane], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Female Animal Path Pein (S)" 3 Skill.new { Skill.name="Giant Crab", Skill.desc="Pre-selects this animal for the next use of 'Animal Path Summoning'. When active, Female Animal Path and her allies become invulnerable to non-affliction skills for 1 turn.", Skill.classes=[Physical], Skill.cost=[], Skill.cooldown=0 }] ] Original "classic-female-animal-path-pein-s",
 Character "White Zetsu (S)" 0 "A countless army born from Hashirama's cells—harmless in appearance, deadly in numbers. Character submited by: Akats." [] [[Rules.configure "White Zetsu (S)" 0 Skill.new { Skill.name="White Zetsu Host", Skill.desc="White Zetsu cannot become invulnerable permanently. Each turn he gains 3 clone stacks, and if stunned will gain 15 points of unpierceable damage reduction the following turn. At 3 clone stacks, he gains 15 points of damage reduction. At 6, he gains 15 destructible defense. At 9, he ignores affliction damage. Each skill he uses consumes 6 clone stacks.", Skill.classes=[Physical], Skill.cost=[], Skill.cooldown=4 }],
    [Rules.configure "White Zetsu (S)" 1 Skill.new { Skill.name="Clones Assault", Skill.desc="At 3/6/9 clones, this skill costs 1 additional random chakra and deals 25/45/65 piercing damage to one enemy. This skill cannot be countered.", Skill.classes=[Physical,Melee], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "White Zetsu (S)" 2 Skill.new { Skill.name="Mass Reproduction", Skill.desc="White Zetsu Clones will mass produce all over the battlefield for 4 turns, dealing 10 damage to one random enemy while one random ally will gain 10 points of damage reduction. During this time, this skill becomes 'Parasitic Grab'.", Skill.classes=[Physical,Melee], Skill.cost=[Rand], Skill.cooldown=4 },Rules.configure "White Zetsu (S)" 4 Skill.new { Skill.name="Parasitic Grab", Skill.desc="White Zetsu will make one enemy unable to target anyone else but White Zetsu for 1 turn. They will take 50% more damage from White Zetsu's skills for 2 turns.", Skill.classes=[Physical,Melee], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "White Zetsu (S)" 3 Skill.new { Skill.name="White Assimilation: Poison Mist", Skill.desc="White Zetsu will target all enemies on the battlefield for 2 turns. All enemies will become invulnerable to friendly skills and take 5 additional damage from White Zetsu's skills.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=3 }] ] Original "classic-white-zetsu-s",
 Character "Shinobi Alliance Naruto (S)" 0 "Having gained complete control of all of the kyuubi's chakra, Naruto will be sure to rampage over every battlefield he comes across." [] [[Rules.configure "Shinobi Alliance Naruto (S)" 0 Skill.new { Skill.name="Rasengan Riot", Skill.desc="By forming multiple Rasengan over his head, Naruto deals 30 damage to one enemy. A random teammate of that enemy will also be dealt 20 damage. The following turn, this skill will be replaced by 'Planetary Rasengan'.", Skill.classes=[Chakra,Melee], Skill.cost=[Rand,Rand], Skill.cooldown=0 },Rules.configure "Shinobi Alliance Naruto (S)" 4 Skill.new { Skill.name="Planetary Rasengan", Skill.desc="Naruto forms a big Rasengan surrounded by other Rasengans, targeting one enemy and dealing 35 damage to them. If this skill kills that enemy, Naruto will deal 10 additional damage for 2 turns and will be unable to be killed during this time.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Naruto (S)" 1 Skill.new { Skill.name="Rasenkyugan", Skill.desc="Naruto grabs multiple enemies and smashes them into a giant Rasengan, dealing 15 piercing damage to all enemies for 1 turn. This skill will deal an additional 5 damage when it's used. The following turn, this skill will be replaced by 'Mini-Bijuudama'.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin], Skill.cooldown=0 },Rules.configure "Shinobi Alliance Naruto (S)" 5 Skill.new { Skill.name="Mini-Bijuudama", Skill.desc="By compressing chakra, Naruto creates a miniature of Bijuudama and deals 35 affliction damage to one enemy. For 1 turn, that enemy's skills will deal 10 less non-affliction damage and the cost of their skills will be increased by 1 random chakra.", Skill.classes=[Bane,Melee], Skill.cost=[Nin,Blood], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Naruto (S)" 2 Skill.new { Skill.name="Summoning: Mayhem", Skill.desc="Naruto summons Mayhem in the battlefield. For 1 turn, the first harmful skill used on Naruto will be countered. The countered enemy will receive 15 additional damage from 'Mini Rasenshuriken'. The following turn, this skill will be replaced by 'Mini-Rasenshuriken'. This skill is invisible.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=2 },Rules.configure "Shinobi Alliance Naruto (S)" 6 Skill.new { Skill.name="Mini-Rasenshuriken", Skill.desc="Naruto targets one enemy, destroying their destructible defense and dealing 15 piercing damage to them. This skill cannot be countered or reflected.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Naruto (S)" 3 Skill.new { Skill.name="Supersonic Speed", Skill.desc="This skill makes Shinobi Alliance Naruto (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-naruto-s",
 Character "Shinobi Alliance Sakura (S)" 0 "With her extensive training under Tsunade for the last two and a half years, Sakura has gained a greater understanding of healing and the human body. While Sakura's physical strength and healing prowess have both increased, her greatest ability is a powerful chakra storing seal taught to her by Tsunade." [] [[Rules.configure "Shinobi Alliance Sakura (S)" 0 Skill.new { Skill.name="Empowered Devasting Punch", Skill.desc="Amplifying her strength, Sakura deals 20 damage to one enemy and 5 damage to all others. While 'Strength of a Hundred Seal' is active, this skill will deal 35 damage to one enemy, and 10 to all others.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Sakura (S)" 1 Skill.new { Skill.name="Superior Healing", Skill.desc="With her superior healing skills, Sakura heals half of one ally's missing health, rounded down, and removes all enemy affliction effects from them. While 'Strength of a Hundred Seal' is active, this skill will cost 1 random and have no cooldown.", Skill.classes=[Chakra], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Sakura (S)" 2 Skill.new { Skill.name="Strength of a Hundred Seal", Skill.desc="Sakura gains 3 Seals. During this time, each time Sakura uses a skill other than her invulnerability, she will use up 1 Seal. While 'Strength of a Hundred Seal' is active, Sakura can use this skill again for no cost to restore 25 health and remove all harmful effects on her.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Sakura (S)" 3 Skill.new { Skill.name="Summoning: Katsuyu", Skill.desc="This skill makes Shinobi Alliance Sakura (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-sakura-s",
 Character "Shinobi Alliance Sai (S)" 0 "Sai became capable of using a wider variety of techniques after improving his skills with his animal paintings. Besides that, Sai carries with him his powerful Sealing Technique." [] [[Rules.configure "Shinobi Alliance Sai (S)" 0 Skill.new { Skill.name="Tiger Vision Staring Bullet", Skill.desc="By using this sealing technique, Sai stuns one enemy's harmful skills permanently and deals 25 damage to them each turn. If that enemy uses a new skill, this skill will end and Sai gains 1 genjutsu chakra. This skill ends if Sai is killed.", Skill.classes=[Physical,Melee], Skill.cost=[Gen,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Sai (S)" 1 Skill.new { Skill.name="Great Beast Painting: Kamikaze Birds", Skill.desc="Sai makes one enemy receive 5 additional damage from non-affliction skills* and deals them 10 piercing damage to them each turn permanently. If that enemy uses a new skill, they will take 20 piercing damage and then this skill will end. This skil ends if Sai is killed.", Skill.classes=[Physical,Ranged], Skill.cost=[Gen], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Sai (S)" 2 Skill.new { Skill.name="Great Beast Painting: Ink Warriors", Skill.desc="Sai grants one ally and himself 20 points of destructible defense. If that ally's destructible defense is destroyed, 'Great Beast Painting: Kamikaze Birds' will have no cost for 1 turn. If Sai destructible defense is destroyed, 'Tiger Vision Staring Bullet' will cost 1 random chakra for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand,Rand], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Sai (S)" 3 Skill.new { Skill.name="Sai Kunai Parry", Skill.desc="This skill makes Shinobi Alliance Sai (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-sai-s",
 Character "Shinobi Alliance Kakashi (S)" 0 "Kakashi, as one of the squad leaders, goes to war alongside all the ninjas. Now, he uses everything at his disposal to win. Besides himself, Kakashi can rely on his allies." [] [[Rules.configure "Shinobi Alliance Kakashi (S)" 0 Skill.new { Skill.name="Kubikiribouchou: Heavy Attack", Skill.desc="Using Zabuza's sword, Kakashi destroys one enemy's destructible defense and deals 15 piercing damage to them. Afterwards, Kakashi will also steal 5 health from that enemy. The following turn, 'Lightning-Infused Kunai' will cost 1 ninjutsu and 1 random chakra.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Kakashi (S)" 1 Skill.new { Skill.name="Lightning-Infused Kunai", Skill.desc="Kakashi deals 40 piercing damage to one enemy, ignoring counters and reflects. If this skill successfully kills the target, it will have its cooldown reset, its chakra cost changed to 2 random chakra, and its damage increased by 10 for 1 turn.", Skill.classes=[Chakra,Ranged], Skill.cost=[Tai,Nin], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Kakashi (S)" 2 Skill.new { Skill.name="Lightning Transmission Cable", Skill.desc="For 3 turns, Kakashi gains 15 points of damage reduction and any enemy that uses a new non-mental skill on him will take 10 piercing damage. During this time, all enemies will be marked and, if they use a new harmful damaging skill, Kakashi's other skills will permanently steal 5 health from them, dealt as a new source of damage. This effect stacks.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Kakashi (S)" 3 Skill.new { Skill.name="Earth Release: Earth-Style Wall", Skill.desc="This skill makes Shinobi Alliance Kakashi (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-kakashi-s",
 Character "Shinobi Alliance Shikamaru (S)" 0 "Shikamaru, now in the war. He remains a good and talented ninja, using his shadows more effectively, in addition to using the help of his allies very well, and forcing his enemies to help him too." [] [[Rules.configure "Shinobi Alliance Shikamaru (S)" 0 Skill.new { Skill.name="Continuous Shadow Sewing", Skill.desc="Shikamaru deals 30 piercing damage to one enemy and stuns their non-chakra skills for 1 turn. If that enemy doesn't use any new skill, they will take 15 additional piercing damage. During 'Tatical Range Increase', this skill will deal 15 additional damage.", Skill.classes=[Chakra,Ranged], Skill.cost=[Gen,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Shikamaru (S)" 1 Skill.new { Skill.name="Tatical Range Increase", Skill.desc="For 1 turn, Shikamaru will ignore all damage dealt and will target all enemies. During this time, the enemies that use a new skill will be able to be target of 'Tatical Shadow Bind' for 1 turn. This skill becomes 'Tatical Shadow Bind' for 1 turn and is invisible.", Skill.classes=[Chakra,Ranged], Skill.cost=[Tai], Skill.cooldown=2 },Rules.configure "Shinobi Alliance Shikamaru (S)" 4 Skill.new { Skill.name="Tatical Shadow Bind", Skill.desc="Shikamaru deals 30 damage to all enemies affected by 'Tatical Range Increase', and for 2 turns stuns their physical and chakra skills.", Skill.classes=[Chakra,Ranged], Skill.cost=[Gen,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Shikamaru (S)" 2 Skill.new { Skill.name="Ally Shadow Control", Skill.desc="Shikamaru target one ally for 3 turns, making their skills have 1 cooldown decreased, and if Shikamaru uses a new skill that ally will become invulnerable to damage skills for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Shikamaru (S)" 3 Skill.new { Skill.name="Hide and Thinking", Skill.desc="This skill makes Shinobi Alliance Shikamaru (S) invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-shikamaru-s",
 Character "Shinobi Alliance Chouji (S)" 0 "After nearly three years, Chouji has developed in both strength and size, mastering the Akimichi clan techniques. No longer does Chouji need the Akimichi pills to tap into his true strength, instead, he merely needs to control his chakra and become a force to reckon with." [] [[Rules.configure "Shinobi Alliance Chouji (S)" 0 Skill.new { Skill.name="Butterfly Bullet Bombing", Skill.desc="Chouji slams his fist into an enemy's face, first ignoring all harmful effects other than chakra cost changes for 1 turn and then dealing 30 damage to one enemy. This skill cannot be countered or reflected and Chouji's skills will cost 2 additional random chakra afterwards.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Rand,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Chouji (S)" 1 Skill.new { Skill.name="Human Bullet Tank", Skill.desc="Chouji rolls over one enemy for 2 turns, dealing 15 damage to them. During this time, Chouji will counter all new physical and chakra skills used on him.* This skill will increase the cost of Chouji's skills by 1 random chakra each turn.", Skill.classes=[Physical,Melee], Skill.cost=[Blood,Rand,Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Chouji (S)" 2 Skill.new { Skill.name="Butterfly Control", Skill.desc="Using his new found control, Chouji taps into even more power. This skill will be replaced by 'Super-Punch'. Each turn, the existing cost of Chouji's skills will be decreased by 1 random chakra.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=0 },Rules.configure "Shinobi Alliance Chouji (S)" 4 Skill.new { Skill.name="Super-Punch", Skill.desc="Chouji punches an enemy down with a fistful of chakra, removing all Harmfull effects on him and then dealing 30 damage to one enemy, this skill cannot be countered or reflected and chouji skills cost 2 additional random chakras afterwards.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin,Rand,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Chouji (S)" 3 Skill.new { Skill.name="Butterfly Block", Skill.desc="This skill makes Shinobi Alliance Chouji (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand,Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-chouji-s",
 Character "Shinobi Alliance Ino (S)" 0 "Not one to be left behind, Ino has trained non-stop to improve her abilities and teamwork. With her improved techniques, Ino can not only control her enemies, but her allies too all while seeing everything on the battlefield." [] [[Rules.configure "Shinobi Alliance Ino (S)" 0 Skill.new { Skill.name="Mind Body Switch Interference", Skill.desc="Ino interferes one enemy for 1 turn. The following turn, that enemy will receive 15 piercing damage and if that enemy uses a new harmful skill, they will be countered. If successful, this skill will be replaced by the countered skill, which will cost random chakra. This skill is invisible.", Skill.classes=[Mental,Ranged], Skill.cost=[Gen], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Ino (S)" 1 Skill.new { Skill.name="Enhanced Proxy Surveillance", Skill.desc="For 4 turns all damage reduction and destructible defense effects all enemies use will be reduced by 15, percentage damage reduction will be reduced by 50% and Ino will know when and where any skill is used. This skill can't be countered, reflected and is invisible.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Ino (S)" 2 Skill.new { Skill.name="Mind Clone Switch", Skill.desc="Ino enters the mind of both of her allies, making their bodies fight on regardless of their state. For 3 turns, both of Ino's allies will ignore all harmful effects other than damage and chakra cost changes. This skill is invisible and will end if Ino dies.", Skill.classes=[Mental], Skill.cost=[Gen], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Ino (S)" 3 Skill.new { Skill.name="Ino Dodge", Skill.desc="This skill makes Shinobi Alliance Ino (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-ino-s",
 Character "Shinobi Alliance Shino (S)" 0 "Shino evolves, enhancing his intellect and his Aburame clan abilities. Shino remains calm and, at the same time, cold. His parasites can now destroy any layer, enemy, or defense, and he can also use them as a defense at any moment." [] [[Rules.configure "Shinobi Alliance Shino (S)" 0 Skill.new { Skill.name="Insect Assault", Skill.desc="Shino deals 10 affliction damage to one enemy for 3 turns. During 'Bug Barrier', this skill can be used on Shino, or an ally, to heal 10 health for 3 turns.", Skill.classes=[Bane,Ranged], Skill.cost=[Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Shino (S)" 1 Skill.new { Skill.name="Insect Coffin", Skill.desc="Shino surrounds one enemy with insects, dealing 15 affliction damage to them for 3 turns. During this time, that enemy will be unable to reduce damage or become invulnerable and if Shino or an ally uses a damaging skill, or new action, on that enemy, they will heal 15 health.", Skill.classes=[Bane,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Shino (S)" 2 Skill.new { Skill.name="Bug Barrier", Skill.desc="Shino creates a massive barrier of bugs to defend his team. For 1 turn, Shino and his allies will heal 15 health and will gain 15 destructible defense. Afterwards, they will heal 5 health permanently in the following turns. This skill ends if Shino dies, and it will be re-applied if used while active.", Skill.classes=[Chakra], Skill.cost=[Blood,Blood], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Shino (S)" 3 Skill.new { Skill.name="Hidden Insects", Skill.desc="This skill makes Shinobi Alliance Shino (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-shino-s",
 Character "Shinobi Alliance Hinata (S)" 0 "Hinata will also take part in the war. Together with her allies, she will destroy any enemy that tries to attack using her new technique, Gentle Step Twin Lion Fists, along with her Byakugan." [] [[Rules.configure "Shinobi Alliance Hinata (S)" 0 Skill.new { Skill.name="Sixty-Four Palms", Skill.desc="Hinata delivers a series of attacks to one enemy, dealing 25 piercing damage to them and stunning their chakra skills for 1 turn. While improved, this skill will stun non-mental skills for 1 turn instead.", Skill.classes=[Chakra,Melee], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Hinata (S)" 1 Skill.new { Skill.name="Gentle Step Twin Lion Fists", Skill.desc="Hinata assaults one enemy with her twin lion fists, dealing 30 piercing and removing 1 taijutsu or ninjutsu chakra from them. The following 2 turns, this skill will be replaced by 'Chakra Lion Attack'. While improved, this skill will deal 35 piercing damage and remove 1 random chakra instead.", Skill.classes=[Chakra,Melee], Skill.cost=[Blood,Rand], Skill.cooldown=2 },Rules.configure "Shinobi Alliance Hinata (S)" 4 Skill.new { Skill.name="Chakra Lion Attack", Skill.desc="This skill deals 25 piercing damage to one enemy and removes 1 taijutsu or ninjutsu chakra. While improved, this skill will remove 1 random chakra instead.", Skill.classes=[Chakra,Melee], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Hinata (S)" 2 Skill.new { Skill.name="Byakugan: Enhanced Vision", Skill.desc="For 4 turns, Hinata's non-damage effects cannot be ignored and her skills will be improved. During this time, Hinata will use her Byakugan to reveal any invisible skill used by the enemy team.", Skill.classes=[Mental,Ranged], Skill.cost=[Rand], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Hinata (S)" 3 Skill.new { Skill.name="Byakugan: Focus", Skill.desc="This skill makes Shinobi Alliance Hinata (S) invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-hinata-s",
 Character "Shinobi Alliance Kiba (S)" 0 "Now in the war, Kiba is one of the most powerful close-range combatants. Utilizing the vast arsenal of the Inuzuka clan, Kiba can combat even colossal enemies with Akamaru and their tornado fang." [] [[Rules.configure "Shinobi Alliance Kiba (S)" 0 Skill.new { Skill.name="Tornado Fang", Skill.desc="Kiba deals 30 piercing damage to one enemy and makes them deal 10 less non-affliction damage for 1 turn. During 'Three Headed Wolf', this skill will deal 10 additional damage.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Kiba (S)" 1 Skill.new { Skill.name="Three Headed Wolf", Skill.desc="Kiba removes all harmful physical and chakra skills from his team and, for 3 turns, targets all enemies. During this time, enemies that use a new harmful skill will take 5 piercing damage and permanently receive 5 additional damage from physical melee skills. This skill is replaced by 'Tail Rotating Fang'.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Blood], Skill.cooldown=0 },Rules.configure "Shinobi Alliance Kiba (S)" 4 Skill.new { Skill.name="Tail Rotating Fang", Skill.desc="Kiba deals 45 piercing damage to one enemy and becomes invulnerable to physical skills. Permanently, both Kiba and that enemy will deal 5 less physical damage.", Skill.classes=[Physical,Melee], Skill.cost=[Blood,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Kiba (S)" 2 Skill.new { Skill.name="Man Animal Tatics", Skill.desc="Kiba and one ally will deal 5 additional damage with non-affliction skills for 2 turns. During this time, every time a new enemy harmful skill is used on them, their skills will cost 1 less random chakra for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Kiba (S)" 3 Skill.new { Skill.name="Kiba Block", Skill.desc="This skill makes Shinobi War Kiba (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-kiba-s",
 Character "Shinobi Alliance Tenten (S)" 0 "During the Fourth Shinobi World War, Tenten joins the Shinobi Alliance and takes possession of the Bashousen, one of the treasured tools of the Sage of the Six Paths. By channeling large amounts of chakra through the fan, she can unleash elemental devastation or adapt its power to protect her allies." [] [[Rules.configure "Shinobi Alliance Tenten (S)" 0 Skill.new { Skill.name="Bashousen: Coil of Fire", Skill.desc="Using the Sage of the Six Paths' legendary leaf fan, Tenten blasts her enemies with a sea of raging fire, dealing 15 damage and 15 affliction damage* to them. The following 3 turns, they will take 5 affliction damage.", Skill.classes=[Physical,Bane,Ranged], Skill.cost=[Tai,Nin,Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Tenten (S)" 1 Skill.new { Skill.name="Bashousen: Coil of Wind", Skill.desc="Using the Bashousen to throw a gust of wind, the following turn all non-mental skills used on Tenten or her team will be reflected back to the enemy. This skill is invisible.", Skill.classes=[Physical], Skill.cost=[Tai,Nin,Rand], Skill.cooldown=3 }],
    [Rules.configure "Shinobi Alliance Tenten (S)" 2 Skill.new { Skill.name="Bashousen: Strike", Skill.desc="If used on an enemy, deals 15 affliction damage. If used on herself, or an ally, grants 15 points of destructible defense. If used after 'Bashousen: Coil of Fire', this will also deal 5 affliction damage permanently. If used after 'Bashousen: Coil of Wind', this will also reflect non-mental skills for 1 turn; Invisible.", Skill.classes=[Bane,Ranged], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Tenten (S)" 3 Skill.new { Skill.name="Reflective Paper Bombs", Skill.desc="This skill makes Shinobi Alliance Tenten (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-tenten-s",
 Character "Shinobi Alliance Lee (S)" 0 "Now a chuunin, Lee has trained endlessly with Gai, and not only learned new abilities, but has learned what it truly means to fight. In battle, Lee now fights for his friends and allies, growing stronger as they fall around him." [] [[Rules.configure "Shinobi Alliance Lee (S)" 0 Skill.new { Skill.name="Konoha Rising Wind", Skill.desc="Lee tries to hinder an enemy, dealing 15 damage to them and lowering all their non-affliction damage by 15 for 2 turns. This skill will deal an additional 10 damage, and the damage reduction effect will last 1 additional turn for each ally that is dead.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Lee (S)" 1 Skill.new { Skill.name="Konoha Great Whirlwind", Skill.desc="Lee gains momentum, dealing 25 damage to one enemy and gaining 10 points of damage reduction for 1 turn. The following turn this skill will deal an additional 10 damage and grant 10 more damage reduction. This skill will deal an additional 10 damage for every ally that has been killed.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Lee (S)" 2 Skill.new { Skill.name="One-Man Front Lotus", Skill.desc="Using a modified version of Front Lotus, Lee dives down on an opponent, dealing 20 damage to them. This skill will deal an additional 20 damage for each ally that is dead, and an additional 20 damage for each 30 health that Lee has lost.", Skill.classes=[Physical,Melee], Skill.cost=[Rand,Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Lee (S)" 3 Skill.new { Skill.name="Lee Heavy Block", Skill.desc="This skill makes Rock Lee (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-lee-s",
 Character "Shinobi Alliance Temari (S)" 0 "At the outset of the Fourth Shinobi World War, Temari is placed in the Fourth Division. Although Gaara is officially in command of the division and Shikamaru is in Gaara's proxy, Temari is the one who leads the division on the battlefield, including personally commanding the division's Wind Release combat unit." [] [[Rules.configure "Shinobi Alliance Temari (S)" 0 Skill.new { Skill.name="Third Moon Unleash", Skill.desc="Temari unleashes her fan with all three moons revealed. For 4 turns, Temari's skilLs will cost 1 less random chakra. During this time, any enemy that uses a new skill on Temari will receive 5 additional damage from her permanently.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Temari (S)" 1 Skill.new { Skill.name="Temari Air Slash", Skill.desc="Temari sweeps her fan to create a slicing current of wind. For 1 turn, Temari becomes invulnerable to non-mental skills, deals 15 piercing damage to one enemy and stuns their non-mental skills. The following turn, that enemy will be dealt 15 damage.", Skill.classes=[Physical,Ranged], Skill.cost=[Nin,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Temari (S)" 2 Skill.new { Skill.name="Summoning: Kamatari", Skill.desc="Summoning Kamatari, Temari deals 40 piercing damage to one enemy. After used, if the target of this skill is killed, Temari gains 1 random chakra.", Skill.classes=[Chakra,Melee], Skill.cost=[Rand,Rand,Rand], Skill.cooldown=2 }],
    [Rules.configure "Shinobi Alliance Temari (S)" 3 Skill.new { Skill.name="Fan Heavy Block", Skill.desc="This skill makes Shinobi Alliance Temari (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-temari-s",
 Character "Shinobi Alliance Kankuro (S)" 0 "During the Fourth Shinobi World War, Kankurou is put in charge of the Surprise Attack Division, leading his squad as a guerrilla unit. Heading into the war, Kankurou greatly expanded his arsenal, adding the puppets of Sasori and his parents, and will fight using all his weapons in perfect tandem with each other." [] [[Rules.configure "Shinobi Alliance Kankuro (S)" 0 Skill.new { Skill.name="Kankuro: Puppet Mastery", Skill.desc="Kankuro prepares his puppets, gaining 25 unpierceable damager reduction. If Kankuro is targeted by a new harmful non-affliction damaging skill, he will lose 5 points of damage reduction from this skill. If used while active, it will be re-aplied.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Kankuro (S)" 1 Skill.new { Skill.name="Puppet Manipulation: Sasori", Skill.desc="Kankuro targets all enemies, dealing damage to them equal the amount of damage reduction points that 'Kankuro: Puppet Mastery' currently has. If 'Kankuro: Puppet Mastery' has 15 points of damage reduction or less, this skill will cost 1 less random chakra.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Kankuro (S)" 2 Skill.new { Skill.name="Puppet Manipulation: Father and Mother", Skill.desc="Kankuro protects himself or an ally, granting them 10 destructible defense for each 5 points of damage reduction that 'Kankuro: Puppet Mastery' currently has. If 'Kankuro: Puppet Mastery' has 15 points of damage reduction or less, this skill will cost 1 less random chakra.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand,Rand], Skill.cooldown=4 }],
    [Rules.configure "Shinobi Alliance Kankuro (S)" 3 Skill.new { Skill.name="Kankuro Sealing Technique", Skill.desc="This skill makes Shinobi Alliance Kankuro (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-kankuro-s",
 Character "Shinobi Alliance Bee (S)" 0 "After his encounter with Kisame, in which the sentient weapon took a liking to his chakra, Killer Bee became the owner of the legendary Shark-Skin Blade, Samehada. With it at his side, Bee can use his arsenal of swords more efficiently, combining them with Samehada's ability to absorb chakra." [] [[Rules.configure "Shinobi Alliance Bee (S)" 0 Skill.new { Skill.name="Sting Pierce", Skill.desc="Bee deals 15 piercing damage to one enemy, marking them for 3 turns. For 1 turn, Bee will nullify the first harmful physical or chakra skill used on him. This skill cannot be used on an already marked enemy.", Skill.classes=[Physical,Melee], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Bee (S)" 1 Skill.new { Skill.name="Samehada Monstruous Drain", Skill.desc="Bee targets all enemies marked by 'Sting Pierce', stealing 15 health and 1 bloodline or ninjutsu chakra.", Skill.classes=[Bane,Melee], Skill.cost=[Tai,Rand], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Bee (S)" 2 Skill.new { Skill.name="Hachibi Chakra Cloak", Skill.desc="Bee releases his jinchuuriki chakra, gaining 20 points of destructible defense. During this time, he will heal 10 health each turn. When destroyed, this skill will end and, for 1 turn, Bee's entire team will deal 5 additional non-affliction damage. While active, this skill will be replaced by 'Fatal Sting'.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=3 },Rules.configure "Shinobi Alliance Bee (S)" 4 Skill.new { Skill.name="Fatal Sting", Skill.desc="Bee deals 25 piercing damage to one enemy and reduces their non-affliction damage to a maximum of 10 for 1 turn. If that enemy is marked by 'Sting Pierce', they will receive 15 additional damage.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Shinobi Alliance Bee (S)" 3 Skill.new { Skill.name="Bee Block", Skill.desc="This skill makes Shinobi Alliance Bee (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-bee-s",
 Character "Shinobi Alliance Mei (S)" 0 "As the Fifth Mizukage, Mei Terumi joins the Allied Shinobi Forces during the Fourth Shinobi World War. Combining her mastery of Water Release with her corrosive kekkei genkai, she controls the battlefield while protecting the alliance." [] [[Rules.configure "Shinobi Alliance Mei (S)" 0 Skill.new { Skill.name="Water Dragon Bomb", Skill.desc="Mei deals 25 damage to one enemy and stuns their skills for 1 turn. Afterwards, all other enemies will have the cost of their skills increased by 1 random chakra.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Mei (S)" 1 Skill.new { Skill.name="Acid Mud", Skill.desc="Mei deals 10 affliction damage to all enemies for 1 turn, permanently lowering all their non-affliction damage by 5 until they use a new non-affliction damage skill. This skill's non-damage effects will be re-applied if a new stunning skill is used on an affected enemy. Each stack is removed once. Ends when Mei dies.", Skill.classes=[Bane,Melee], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Mei (S)" 2 Skill.new { Skill.name="Silent Mist", Skill.desc="For 1 turn, if one enemy uses a new skill, they will be stunned for 1 turn in the primary class of that skill. This skill is invisible.", Skill.classes=[Bane,Ranged], Skill.cost=[], Skill.cooldown=1 }],
    [Rules.configure "Shinobi Alliance Mei (S)" 3 Skill.new { Skill.name="Mei Flee", Skill.desc="This skill makes Shinobi Alliance Mei (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-shinobi-alliance-mei-s",
 Character "Edo Tensei Mangetsu (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War as one of the Seven Swordsmen of the Mist, Mangetsu was widely feared as the 'Second Coming of the Demon'. The older brother of Suigetsu, Mangetsu primarily used the Twin Sword, Hiramekarei, though he was famously a master of all seven blades." [] [[Rules.configure "Edo Tensei Mangetsu (S)" 0 Skill.new { Skill.name="Hydrification Technique", Skill.desc="ET Mangetsu steals 20 health points from one enemy. For 1 turn, a random skill class will be chosen, and ET Mangetsu will ignore all enemy skills of that class, or none if no class is chosen.", Skill.classes=[Bane,Melee], Skill.cost=[Gen,Rand], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Mangetsu (S)" 1 Skill.new { Skill.name="Impure World Regeneration", Skill.desc="When this skill is used, ET Mangetsu will heal 2 health every turn for the rest of the game. This skill stacks and may only be used 5 times.", Skill.classes=[Mental], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Mangetsu (S)" 2 Skill.new { Skill.name="Mist Sword Summoning", Skill.desc="Mangetsu randomly summons one of the Seven Swords, granting 'Hydrification Technique' a random unique effect every turn. Hiramekarei: Steals 10 additional health. / Kubikiribocho: Grants 10 permanent destructible defense. / Sameheada: Steals 1 random chakra from the target. / Nuibari: Stuns non-mental skills for 1 turn. / Shibuki: Deals 5 permanent affliction damage. / Kabutowari: Destroys destructible defense and deals 15 piercing damage. / Kiba: Deals 20 affliction damage to all other enemies.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Mangetsu (S)" 3 Skill.new { Skill.name="Mangetsu Block", Skill.desc="This skill makes Edo Tensei Mangetsu (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-mangetsu-s",
 Character "Edo Tensei Itachi (S)" 0 "One of the five past Akatsuki members reanimated by Kabuto during the Fourth Shinobi World War, Itachi sees this as an opportunity to pursue his true goals and set things right with Naruto and Sasuke. Freeing himself from Kabuto's shackles, Itachi unleashes the full power of the Uchiha with his deathless body." [] [[Rules.configure "Edo Tensei Itachi (S)" 0 Skill.new { Skill.name="Phoenix Flower Shuriken", Skill.desc="Itachi unleashes a volley of fire-infused shuriken, dealing 10 affliction damage to all enemies. For 1 turn, if they use a new harmful skill, they will have 'Phoenix Flower Shuriken' re-applied on them.", Skill.classes=[Bane,Ranged], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Itachi (S)" 1 Skill.new { Skill.name="Demonic Illusion: Mirage Crow", Skill.desc="For 2 turns, one enemy will be unable to reduce damage or become invulnerable and will take 15 damage each turn. During this time, Itachi will become invulnerable to that enemy's skills.", Skill.classes=[Mental,Melee], Skill.cost=[Gen,Rand], Skill.cooldown=2 }],
    [Rules.configure "Edo Tensei Itachi (S)" 2 Skill.new { Skill.name="Passive: Edo Tensei Sharingan", Skill.desc="Each turn, this skill will randomly switch between 'Izanami', 'Itachi Mangekyou Sharingan', and 'Itachi Kotoamatsukami'. Each of these skills can only be used once per game. This passive is invisible.", Skill.classes=[Mental], Skill.cost=[], Skill.cooldown=0 },Rules.configure "Edo Tensei Itachi (S)" 4 Skill.new { Skill.name="Edo Tensei Mangekyou Sharingan", Skill.desc="This skill can only be used once to apply both 'Amaterasu' and 'Tsukuyomi' on an enemy; This skill ends when Itachi killed. Amaterasu: Deals 20 affliction damage instantly, and 5 affliction permanently. Tsukuyomi: Fully stuns the enemy's skills for 1 turn.", Skill.classes=[Mental,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 },Rules.configure "Edo Tensei Itachi (S)" 5 Skill.new { Skill.name="Edo Tensei Kotoamatsukami", Skill.desc="This skill can only be used once to target Itachi or an ally permanently. The next time the marked target's health drops to 5 or less, they will instantly heal to 40 health, and then heal 5 health for the following 3 turns. This skill is invisible until triggered.", Skill.classes=[Mental,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 },Rules.configure "Edo Tensei Itachi (S)" 6 Skill.new { Skill.name="Izanami", Skill.desc="This skill can only be used once to target an enemy permanently. The next time that enemy uses a new skill, they will be countered and this skill will end. If successful, the countered skill will be stunned for 3 turns; This duration is increased by the skill's current cooldown. This skill is invisible until triggered.", Skill.classes=[Mental,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Itachi (S)" 3 Skill.new { Skill.name="Itachi Block", Skill.desc="This skill makes Edo Tensei Itachi (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-itachi-s",
 Character "ET Susanoo Itachi (S)" 0 "Having been reanimated once more, Itachi now manifests the full power of his Susanoo in battle. Shielded by the Yata Mirror and wielding the sealing Totsuka Blade, he becomes a relentless force that blends absolute defense with lethal precision." [] [[Rules.configure "ET Susanoo Itachi (S)" 0 Skill.new { Skill.name="Skeletal Blade", Skill.desc="Using his Susanoo's skeletal blade, Itachi deals 20 piercing damage to one enemy. Permanently, that enemy will receive 5 additional damage from harmful skills.", Skill.classes=[Chakra,Melee], Skill.cost=[Blood], Skill.cooldown=1 }],
    [Rules.configure "ET Susanoo Itachi (S)" 1 Skill.new { Skill.name="Interrupting Slice", Skill.desc="Itachi deals 15 piercing damage to one enemy. Permanently, that enemy will deal 5 less non-affliction damage.", Skill.classes=[Chakra,Melee], Skill.cost=[Gen], Skill.cooldown=1 }],
    [Rules.configure "ET Susanoo Itachi (S)" 2 Skill.new { Skill.name="Totsuka Blade Sealing", Skill.desc="Itachi seals one enemy with his Susanoo's legendary blade, dealing 35 affliction damage to them, removing 1 bloodline or genjutsu chakra and stunning their harmful skills for 1 turn. This skill cannot be countered or reflected.", Skill.classes=[Bane,Melee], Skill.cost=[Blood,Gen], Skill.cooldown=2 }],
    [Rules.configure "ET Susanoo Itachi (S)" 3 Skill.new { Skill.name="Edo Tensei Susanoo", Skill.desc="For 3 turns, if Itachi's health drops to 35 or less, Itachi's Susanoo will evolve to the next stage, improving his skills for the following 3 turns. During this time, this skill will be replaced by 'Yasaka Magatama' and Itachi's skills will steal health instead. This skill is invisible.", Skill.classes=[Chakra], Skill.cost=[], Skill.cooldown=0 },Rules.configure "ET Susanoo Itachi (S)" 4 Skill.new { Skill.name="Yasaka Magatama", Skill.desc="Itachi unleashes his strongest long-range technique, dealing 40 piercing damage to all enemies. This skill cannot be countered.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Blood,Gen,Gen], Skill.cooldown=9 }] ] Original "classic-et-susanoo-itachi-s",
 Character "Edo Tensei Yota (S)" 0 "A young child from a nomadic clan, Yota died at an early age, but was revived through Edo Tensei by Orochimaru and kept alive for years as a test subject. A curious, naïve, and sensitive boy, Yota can manipulate the weather around himself, and is deployed by Kabuto to fight in the Fourth Shinobi World War." [] [[Rules.configure "Edo Tensei Yota (S)" 0 Skill.new { Skill.name="Weather Manipulation Rain: Water Wave", Skill.desc="Yota cries, and a sudden wave crashes down on a random enemy, dealing 15 damage to them, and after targets 0 random enemies, dealing 15 damage to each one of them. This skill will target 1 additional random enemy for each 'Rain Stack' that Yota has. Afterwards, Yota gains 1 'Rain Stack'.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Yota (S)" 1 Skill.new { Skill.name="Weather Manipulation Rain: Water Spheres", Skill.desc="Yota gains 15 points of damage reduction* and deals 10 damage to all enemies for 2 turns. Each turn, Yota cries and gains 1 'Rain Stack'. During this time, If Yota is stunned, he will cry even more, gaining 1 additional 'Rain Stack' and healing 10 health.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=2 }],
    [Rules.configure "Edo Tensei Yota (S)" 2 Skill.new { Skill.name="Wather Manipulation Lightning", Skill.desc="Yota sends a devastating lightning strike to obliterate all enemies, dealing 10 affliction damage to them for each 'Rain Stack' Yota currently has.", Skill.classes=[Bane,Ranged], Skill.cost=[Blood,Blood], Skill.cooldown=4 }],
    [Rules.configure "Edo Tensei Yota (S)" 3 Skill.new { Skill.name="Yota is happy don't bother him", Skill.desc="This skill makes Edo Tensei Yota (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-yota-s",
 Character "Edo Tensei Kidoumaru (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War along with his Sound Four teammates, Kidoumaru is happy to be back in action and wreaking havoc once again. Terrorizing the battlefield with his many spider-based jutsu, enhanced by his Cursed Seal, Kidoumaru is a menace to all who cross his path." [] [[Rules.configure "Edo Tensei Kidoumaru (S)" 0 Skill.new { Skill.name="The Spider's Web", Skill.desc="Kidoumaru enables his skills and targets all enemies permanently. Every time they use a new harmful skill, they will gain 1 'Web Stack'. This skill ignores invulnerability and will be replaced by 'Sticky Golden Arrow'.", Skill.classes=[Physical,Ranged], Skill.cost=[], Skill.cooldown=0 },Rules.configure "Edo Tensei Kidoumaru (S)" 4 Skill.new { Skill.name="Sticky Golden Arrow", Skill.desc="Using the Sticky Golden Arrow, Kidoumaru destroys all destructible defense one enemy has and deals 25 piercing damage to them, consuming all 'Web Stacks' they have to deal 10 additional damage per stack.", Skill.classes=[Physical,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=2 }],
    [Rules.configure "Edo Tensei Kidoumaru (S)" 1 Skill.new { Skill.name="Sticky Gold Kunai", Skill.desc="Kidoumaru deals 20 piercing damage to one enemy and stuns their non-mental skills for 1 turn. Afterwards, all enemies will be dealt 5 piercing damage for each 'Web Stack' they have.", Skill.classes=[Physical,Ranged], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Kidoumaru (S)" 2 Skill.new { Skill.name="Giant Spider Web", Skill.desc="Kidoumaru traps all enemies in a giant web, granting them 1 additional 'Web Stack' and then making them deal 10 less non-affliction damage for 1 turn. This skill cannot be countered.", Skill.classes=[Physical,Ranged], Skill.cost=[Blood], Skill.cooldown=2 }],
    [Rules.configure "Edo Tensei Kidoumaru (S)" 3 Skill.new { Skill.name="Curse Mark Third Eye", Skill.desc="Kidoumaru activates his Curse Mark, becoming invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-kidoumaru-s",
 Character "Edo Tensei Sakon (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War along with their Sound Four teammates, Sakon and Ukon relish being on the battlefield once again. Dynamically splitting and merging their bodies through the use of their Cursed Seal, the twins fight as a powerful unit, showing no mercy to anyone." [] [[Rules.configure "Edo Tensei Sakon (S)" 0 Skill.new { Skill.name="Enhanced Gatling Punch", Skill.desc="Sakon rapidly punches one enemy, dealing 20 damage and 15 piercing damage to them. For 1 turn, that enemy will deal 15 less non-affliction damage. The following turn, 'Parasite Demon' will be improved and fully stun the target instead.", Skill.classes=[Physical,Melee], Skill.cost=[Tai,Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Sakon (S)" 1 Skill.new { Skill.name="Parasite Demon", Skill.desc="Sakon enters an enemy's body, dealing 20 affliction damage to them and stunning their physical and chakra skills for 1 turn. This skill cannot be used on the same target next turn. The following turn, 'Enhanced Gatling Punch' will deal 5 additional damage.", Skill.classes=[Bane,Melee], Skill.cost=[Blood], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Sakon (S)" 2 Skill.new { Skill.name="Summoning: Triple Rashoman", Skill.desc="Sakon summons the walls of Triple Rashoman, removing all harmful skills from himself and gaining 15 points of destructible defense for every skill he has used in the game. This skill will increase its current cooldown by 1 for every 15 destructible defense granted. These stacks reset when used.", Skill.classes=[Chakra], Skill.cost=[Rand,Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Sakon (S)" 3 Skill.new { Skill.name="Sakon: Chakra Unseal", Skill.desc="This skill makes Sakon invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-sakon-s",
 Character "Edo Tensei Tayuya (S)" 0 "Edo Tensei Tayuya was resurrected by Kabuto as a cruel battlefield conductor, her malice and arrogance undimmed by death. She uses her cursed flute to summon demonic warriors and unravel enemies through sound-based genjutsu and mental pressure. As the fight drags on, her control tightens, turning chaos into a carefully orchestrated nightmare." [] [[Rules.configure "Edo Tensei Tayuya (S)" 0 Skill.new { Skill.name="Demonic Melody", Skill.desc="Tayuya deals 5 affliction damage to all enemies for 3 turns. During this time, if they use a new harmful damaging skill, Tayuya will steal 5 health from them. The following 3 turns, 'Doki Ghost' will be improved.", Skill.classes=[Bane,Ranged], Skill.cost=[Gen,Rand], Skill.cooldown=3 }],
    [Rules.configure "Edo Tensei Tayuya (S)" 1 Skill.new { Skill.name="Doki Ghost", Skill.desc="Tayuya summons her doki ghosts, dealing 20 affliction damage to one enemy. While improved, this skill will steal 20 health and 1 ninjutsu or bloodline chakra instead.", Skill.classes=[Bane,Ranged], Skill.cost=[Gen,Rand], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Tayuya (S)" 2 Skill.new { Skill.name="Summoning: Doki Demons", Skill.desc="For 1 turn, the first harmful damaging skill used on her or an ally will be countered. If successful, the countered enemy will be dealt 5 damage and will have their harmful skills stunned for 1 turn. This skill is invisible.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=2 }],
    [Rules.configure "Edo Tensei Tayuya (S)" 3 Skill.new { Skill.name="Tayuya: Chakra Unseal", Skill.desc="This skill makes Edo Tensei Tayuya (S) invulnerable for 1 turn.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-tayuya-s",
 Character "Edo Tensei Fuu (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War, Fuu has had the Seven-Tails, Choumei, sealed back inside her. Having been made into one of Tobi's new Six Paths of Pain along with the other fallen jinchuuriki, Fuu is under his full control, skillfully utilizing the Seven-Tails' various insect abilities." [] [[Rules.configure "Edo Tensei Fuu (S)" 0 Skill.new { Skill.name="Majestic Sting", Skill.desc="Fuu deals 15 damage to one enemy. The following turn, that enemy will receive 10 additional damage from Fuu's skills.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Fuu (S)" 1 Skill.new { Skill.name="Nanabi: Flying Assault", Skill.desc="Fuu becomes invulnerable for 1 turn and deals 30 damage to one enemy ignoring invulnerability.", Skill.classes=[Physical,Melee], Skill.cost=[Blood,Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Fuu (S)" 2 Skill.new { Skill.name="Scale Powder Blinding Attack", Skill.desc="Fuu deals 10 piercing damage to one enemy and makes them unable to reduce damage or become invulnerable for 1 turn. The following turn, that enemy will take another 10 damage and will be stunned for 1 turn.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Fuu (S)" 3 Skill.new { Skill.name="Fuu: Rinnegan Awareness", Skill.desc="This skill may be used to cast the last skill used by Fuu, costing random chakra and dealing 5 additional damage. Afterwards, the original version of the casted skill will be unable to be used by Fuu for 1 turn.", Skill.classes=[Mental], Skill.cost=[], Skill.cooldown=4 }] ] Original "classic-edo-tensei-fuu-s",
 Character "Edo Tensei Yugito (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War, Yugito has had the Two-Tails, Matatabi, sealed back inside her. Having been made into one of Tobi's new Six Paths of Pain along with the other fallen jinchuuriki, Yugito is under his full control, fighting her foes using the Two-Tails' fiery feline powers." [] [[Rules.configure "Edo Tensei Yugito (S)" 0 Skill.new { Skill.name="Cat Claws", Skill.desc="Yugito deals 15 damage to one enemy and stuns their non-mental skills for 1 turn.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Yugito (S)" 1 Skill.new { Skill.name="Fiery Mouse Hairball", Skill.desc="Yugito deals 15 damage to one enemy and removes 1 taijutsu chakra from them.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Yugito (S)" 2 Skill.new { Skill.name="Nibi: Rage Punch", Skill.desc="Yugito destroys all destructible defense of one enemy, deals 15 piercing damage to them and kills them if their health drops to 10 or less.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Yugito (S)" 3 Skill.new { Skill.name="Yugito: Rinnegan Awareness", Skill.desc="This skill makes Edo Tensei Yugito (S) invulnerable for 1 turn.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-yugito-s",
 Character "Edo Tensei Yagura (S)" 0 "Resurrected through Edo Tensei, Yagura retains perfect control over the Three-Tails' power. His Water Mirror techniques allow him to capture, store, and return enemy techniques with deadly precision, turning an opponent’s own strength against them while remaining nearly untouchable." [] [[Rules.configure "Edo Tensei Yagura (S)" 0 Skill.new { Skill.name="Water Mirror", Skill.desc="Yagura targets an enemy for 3 turns. If that enemy uses a new harmful skill, that skill will be permanently stored by 'Water Mirror' and they will deal 5 less non-affliction damage for 1 turn. This skill is invisible, ignores invulnerability, and cannot be used on the same target.", Skill.classes=[Chakra,Ranged], Skill.cost=[], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Yagura (S)" 1 Skill.new { Skill.name="Hook Staff Tilt", Skill.desc="Yagura casts a random skill stored by 'Water Mirror' on an enemy. The stored skill is removed. This skill may only be used if 'Water Mirror' has at least one skill stored.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Yagura (S)" 2 Skill.new { Skill.name="Mirror Image", Skill.desc="Yagura uses Mirror Image on an enemy, dealing 30 damage to them. For 1 turn, they will deal 5 less non-affliction damage and a random harmful skill from that enemy will be stored by 'Water Mirror'. The following turn, 'Hook Staff Tilt' will cast 2 random skills stored by 'Water Mirror' at once.", Skill.classes=[Chakra,Ranged], Skill.cost=[Nin,Rand], Skill.cooldown=1 }],
    [Rules.configure "Edo Tensei Yagura (S)" 3 Skill.new { Skill.name="Yagura Partial Tailed Beast Mode", Skill.desc="This skill makes Edo Tensei Yagura (S) invulnerable for 1 turn. The following turn, 'Hook Staff Tilt' will be improved and cost 1 random chakra instead.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=5 }] ] Original "classic-edo-tensei-yagura-s",
 Character "Edo Tensei Roshi (S)" 0 "Reanimated by Kabuto during the Fourth Shinobi World War, Roshi has had the Four-Tails, Son Goku, sealed back inside him. Having been made into one of Tobi's new Six Paths of Pain along with the other fallen jinchuuriki, Roshi is under his full control, spewing the Four-Tails' lava at anyone who might get in his way." [] [[Rules.configure "Edo Tensei Roshi (S)" 0 Skill.new { Skill.name="Multiple Scorching Rocks", Skill.desc="Roshi deals 30 affliction damage to one enemy and 10 affliction damage to a random different enemy. 'Passive: Fiery Body' deals 1 additional damage permanently (stacks).", Skill.classes=[Bane,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 }],
    [Rules.configure "Edo Tensei Roshi (S)" 1 Skill.new { Skill.name="Lava Armor", Skill.desc="Roshi gains 15 unpierceable defense and deals 10 affliction damage to any enemy that uses a new non-mental skill on him for 4 turns. 'Passive: Fiery Body' deals 1 additional damage permanently (stacks).", Skill.classes=[Bane], Skill.cost=[Blood], Skill.cooldown=5 }],
    [Rules.configure "Edo Tensei Roshi (S)" 2 Skill.new { Skill.name="Magma Field", Skill.desc="For 3 turns, Roshi will automatically trigger 'Passive: Fiery Body' at the end of every turn. The following 3 turns, the enemy team will remove/steal 1 less chakra with their skills. During this time, 'Multiple Scorching Rocks' will cost 1 less random energy. 'Passive: Fiery Body' deals 1 additional damage permanently (stacks).", Skill.classes=[Bane,Ranged], Skill.cost=[Rand,Rand], Skill.cooldown=4 }],
    [Rules.configure "Edo Tensei Roshi (S)" 3 Skill.new { Skill.name="Roshi Partial-Tailed Beast Defense", Skill.desc="This skill makes Roshi invulnerable for 1 turn. 'Passive: Fiery Body' deals 1 additional damage permanently (stacks).", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-edo-tensei-roshi-s",
 Character "Young Kushina" 0 "Kushina is a survivor of the Hidden Whirlpool Village's famed Uzumaki clan, and an immigrant into the Hidden Leaf Village after her own village's downfall. Due to her tomboyish and violent nature, and her bright red colored hair, Kushina is known as the \"Red-Hot Habanero\" as she constantly gets into trouble." [] [[Rules.configure "Young Kushina" 0 Skill.new { Skill.name="Red-Hot Habanero", Skill.desc="Kushina uses her strength to protect an ally. The following 3 turns, if Kushina uses 'Fierce Punch' or 'Dropping Kick', the protected ally will heal 15 health. During this time, she will ignore stun effects.", Skill.classes=[Mental], Skill.cost=[Rand], Skill.cooldown=4 }],
    [Rules.configure "Young Kushina" 1 Skill.new { Skill.name="Fierce Punch", Skill.desc="Kushina lands a fierce punch on an enemy, dealing 20 damage to them. The following turn, 'Dropping Kick' will deal 20 additional damage.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=0 }],
    [Rules.configure "Young Kushina" 2 Skill.new { Skill.name="Dropping Kick", Skill.desc="Kushina drops down with a powerful kick, dealing 10 damage to one enemy and stunning their skills for 1 turn. The following turn, 'Fierce Punch' will deal 10 additional damage and will stun an enemy for 1 turn.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Young Kushina" 3 Skill.new { Skill.name="Skilled Landing", Skill.desc="This skill makes Young Kushina invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-young-kushina",
 Character "Young Yahiko (S)" 0 "The Rain Orphans were three children who lost their parents due to the Hidden Rain Village's involvement in the Second Shinobi World War. Yahiko is a stoic boy who leads his team in the fight for survival during the war." [] [[Rules.configure "Young Yahiko (S)" 0 Skill.new { Skill.name="Water Style: Wild Water Wave", Skill.desc="Yahiko spews water in a waterfall-like fashion, dealing 35 piercing damage to one enemy and 25 chakra damage to all others.", Skill.classes=[Chakra,Ranged], Skill.cost=[Rand,Rand,Rand], Skill.cooldown=2 }],
    [Rules.configure "Young Yahiko (S)" 1 Skill.new { Skill.name="Lateral Kick", Skill.desc="Yahiko assaults one enemy with a lateral kick, dealing 20 damage to them and stunning their skills for 1 turn. The following turn, 'Water Style: Wild Water Wave' will cost 1 less random chakra.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Young Yahiko (S)" 2 Skill.new { Skill.name="Descending Fist", Skill.desc="Yahiko assaults one enemy with a descending fist, dealing 20 piercing damage to them and removing 1 taijutsu or bloodline chakra. The following turn, 'Water Style: Wild Water Wave' will cost 1 less random chakra.", Skill.classes=[Physical,Melee], Skill.cost=[Tai], Skill.cooldown=1 }],
    [Rules.configure "Young Yahiko (S)" 3 Skill.new { Skill.name="Magnificent Frog Disguise", Skill.desc="This skill makes Young Yahiko (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-young-yahiko-s",
 Character "Young Nagato (S)" 0 "The Rain Orphans were three children who lost their parents due to the Hidden Rain Village's involvement in the Second Shinobi World War. Nagato is a quiet boy who is not only afraid of the world, but also afraid of himself." [] [[Rules.configure "Young Nagato (S)" 0 Skill.new { Skill.name="Rinnegan Dominion", Skill.desc="Nagato awakens his Rinnegan, gaining 20 points of destructible defense. For 1 turn, 'Wind Style: Air Bullets' and 'Amateur Shinra Tensei' will be improved. Each time this skill is used, its duration and cooldown will increase by 1.", Skill.classes=[Chakra], Skill.cost=[Rand], Skill.cooldown=1 }],
    [Rules.configure "Young Nagato (S)" 1 Skill.new { Skill.name="Wind Style: Air Bullets", Skill.desc="Nagato shoots multiple bullets of air at one enemy, dealing 25 damage and stunning their skills for 1 turn. During 'Rinnegan Dominion', this skill will deal 100% more damage.", Skill.classes=[Chakra,Ranged], Skill.cost=[Blood,Rand], Skill.cooldown=0 }],
    [Rules.configure "Young Nagato (S)" 2 Skill.new { Skill.name="Amateur Shinra Tensei", Skill.desc="By activating Shinra Tensei, Nagato protects one ally. For 1 turn, that ally becomes invulnerable. Afterwards, they will heal 10 health and all harmful skills will be removed from them. During 'Rinnegan Dominion', this skill will cost 1 random chakra instead.", Skill.classes=[Chakra], Skill.cost=[Nin], Skill.cooldown=1 }],
    [Rules.configure "Young Nagato (S)" 3 Skill.new { Skill.name="Majestic Frog Disguise", Skill.desc="This skill makes Young Nagato (S) invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-young-nagato-s",
 Character "Young Konan (S)" 0 "The Rain Orphans were three children who lost their parents due to the Hidden Rain Village's involvement in the Second Shinobi World War. Konan is a sweet girl who always cares more about her teammates than herself." [] [[Rules.configure "Young Konan (S)" 0 Skill.new { Skill.name="Winding Paper Shuriken", Skill.desc="Konan throws paper shuriken with lethal speed, dealing 20 damage to one enemy, and they will ignore all helpful effects for 1 turn.", Skill.classes=[Physical,Ranged], Skill.cost=[Gen], Skill.cooldown=0 }],
    [Rules.configure "Young Konan (S)" 1 Skill.new { Skill.name="Origami Rose", Skill.desc="Konan creates an origami rose, dealing 40 damage to one enemy and stunning their skills for 1 turn. During 'Paper Origami', this skill will cost 1 genjutsu and 1 random chakra instead.", Skill.classes=[Physical,Melee], Skill.cost=[Gen,Gen], Skill.cooldown=1 }],
    [Rules.configure "Young Konan (S)" 2 Skill.new { Skill.name="Paper Origami", Skill.desc="Konan charges her papers at one enemy, dealing 10 damage to them for 3 turns. The following 3 turns, Konan will gain 5 points of damage reduction and ignore all harmful effects except damage. During this time, 'Origami Rose' will be improved.", Skill.classes=[Physical,Ranged], Skill.cost=[Rand], Skill.cooldown=3 }],
    [Rules.configure "Young Konan (S)" 3 Skill.new { Skill.name="Marvelous Frog Disguise", Skill.desc="This skill makes this character invulnerable for 1 turn.", Skill.classes=[Physical], Skill.cost=[Rand], Skill.cooldown=4 }] ] Original "classic-young-konan-s"
 ]
